// Generated by Qleany v1.12.0 from feature_use_case.tera
// Custom implementation (hand-maintained, do NOT blanket-regenerate): a pure file -> file
// transform that converts a Scrivener project into a newest-version `.skrib`, with the
// answers, choices and words the writer's review settled. It touches no store entity (the
// manifest declares `entities: []`); the conversion is the `scrivener_import` crate's, and
// the interface opens the result with the ordinary `load_work`.
//
// A **long operation** (`long_operation: true`): it runs on a background thread, reports
// its phases (opening, reading, converting row by row, writing) through the framework's
// `progress_callback`, and honours `cancel_flag` at every file a folder project reads and
// at every row; on cancel nothing is left on disk.
//
// It does not call `analyze_scrivener_project`: the converter reads the project again
// itself, and refuses one whose fingerprint moved since the review.
use std::path::Path;
use std::sync::Arc;
use std::sync::atomic::AtomicBool;

use crate::ImportScrivenerProjectDto;
use crate::ImportScrivenerProjectResultDto;
use crate::scrivener;
use anyhow::Result;
use common::database::QueryUnitOfWork;
use common::long_operation::{LongOperation, OperationProgress};
use common::types::EntityId;
use scrivener_import::{ProseChoices, Request};

pub trait ImportScrivenerProjectUnitOfWorkFactoryTrait: Send + Sync {
    fn create(&self) -> Box<dyn ImportScrivenerProjectUnitOfWorkTrait>;
}

// A long operation's unit of work must be thread-safe (`Send + Sync`): the use case runs
// on a background thread. This one holds no store action (the feature has
// `entities: []`); it only publishes the completion event.
//
// Exactly the same (empty) list is in ../units_of_work/import_scrivener_project_uow.rs.
pub trait ImportScrivenerProjectUnitOfWorkTrait: QueryUnitOfWork + Send + Sync {
    fn publish_import_scrivener_project_event(&self, ids: Vec<EntityId>, data: Option<String>);
}

pub struct ImportScrivenerProjectUseCase {
    uow_factory: Box<dyn ImportScrivenerProjectUnitOfWorkFactoryTrait>,
    dto: ImportScrivenerProjectDto,
}

impl ImportScrivenerProjectUseCase {
    pub fn new(
        uow_factory: Box<dyn ImportScrivenerProjectUnitOfWorkFactoryTrait>,
        dto: &ImportScrivenerProjectDto,
    ) -> Self {
        ImportScrivenerProjectUseCase {
            uow_factory,
            dto: dto.clone(),
        }
    }
}

impl LongOperation for ImportScrivenerProjectUseCase {
    type Output = ImportScrivenerProjectResultDto;

    fn execute(
        &self,
        progress_callback: Box<dyn Fn(OperationProgress) + Send>,
        cancel_flag: Arc<AtomicBool>,
    ) -> Result<Self::Output> {
        // The phase travels typed, for the interface to word (see `progress`).
        let report = |percent: f32, label: &str| {
            progress_callback(OperationProgress::new(percent, Some(label.to_string())));
        };

        let dto = &self.dto;
        // A choice naming a depth or a row no plan can have is refused by name, before
        // anything is read; the ones in range the converter checks against the plan.
        let choices = scrivener::choices_from_dto(&dto.choices)
            .map_err(|out| crate::failure::for_long_operation(anyhow::Error::new(out)))?;
        let answers = scrivener::import_answers(dto);
        let words = scrivener::words(dto);
        // This computer's host name, to tell a lock left here from one left elsewhere:
        // compared, never kept.
        let options = scrivener_import::Options::default();
        let request = Request {
            source: Path::new(&dto.source_path),
            answers: &answers,
            options: &options,
            choices: &choices,
            prose: ProseChoices {
                blank_lines_as_scene_breaks: dto.blank_lines_as_scene_breaks,
                ornaments_as_scene_breaks: dto.ornaments_as_scene_breaks,
            },
            fingerprint: (!dto.fingerprint.is_empty()).then_some(dto.fingerprint.as_str()),
            output: &dto.output_path,
            overwrite: dto.overwrite,
            words: &words,
            title: dto.title.as_deref(),
            author: dto.author.as_deref(),
            language: dto.language.as_deref(),
            copy_research_files: dto.copy_research_files,
            now: chrono::Utc::now(),
        };

        // Spelled for the `Failed` event by `failure::for_long_operation`: the typed
        // refusal the interface words itself, with the whole chain behind it.
        let summary = scrivener_import::convert(&request, &report, &cancel_flag)
            .map_err(|e| crate::failure::for_long_operation(anyhow::Error::new(e)))?;

        // Notify listeners (parity with every other use case).
        let uow = self.uow_factory.create();
        uow.publish_import_scrivener_project_event(Vec::new(), Some(summary.output_path.clone()));

        Ok(scrivener::summary_to_dto(summary))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::failure::{FailureReason, ProjectImportFailure};
    use crate::units_of_work::import_scrivener_project_uow::ImportScrivenerProjectUnitOfWorkFactory;
    use common::database::db_context::DbContext;
    use common::event::EventHub;

    /// When a test cancels, from the message a progress report carries: a phase code,
    /// or the title of the row just converted.
    type StopAt = Box<dyn Fn(&str) -> bool + Send>;

    /// Import the fixture novel into an empty folder, cancelled from the start when
    /// `preset`, else when `stop_at` says so of a progress report; the folder's contents
    /// afterwards and how the import ended.
    fn cancelled_at(preset: bool, stop_at: StopAt) -> (Vec<std::ffi::OsString>, FailureReason) {
        let dir = match tempfile::tempdir() {
            Ok(dir) => dir,
            Err(e) => panic!("a scratch folder: {e}"),
        };
        let spec = scrivener_fixtures::Spec::novel(
            scrivener_fixtures::Generation::Format20,
            scrivener_fixtures::Platform::Mac,
        );
        let folder = dir.path().join(spec.folder());
        if let Err(e) = spec.build().write_to(&folder) {
            panic!("writing the fixture: {e}");
        }
        let out = dir.path().join("out");
        if let Err(e) = std::fs::create_dir(&out) {
            panic!("an output folder: {e}");
        }
        let db = match DbContext::new() {
            Ok(db) => db,
            Err(e) => panic!("a store: {e}"),
        };
        let hub = Arc::new(EventHub::new());
        let use_case = ImportScrivenerProjectUseCase::new(
            Box::new(ImportScrivenerProjectUnitOfWorkFactory::new(&db, &hub)),
            &ImportScrivenerProjectDto {
                source_path: folder.to_string_lossy().into_owned(),
                output_path: out.join("novel.skrib").to_string_lossy().into_owned(),
                copy_research_files: true,
                manuscript_binder_name: "Manuscrit".into(),
                notes_binder_name: "Notes".into(),
                research_folder_pattern: format!("{} recherches", crate::scrivener::TITLE_SLOT),
                ..ImportScrivenerProjectDto::default()
            },
        );
        let cancel = Arc::new(AtomicBool::new(preset));
        let flag = cancel.clone();
        let progress = Box::new(move |progress: OperationProgress| {
            if stop_at(progress.message.as_deref().unwrap_or_default()) {
                flag.store(true, std::sync::atomic::Ordering::Relaxed);
            }
        });
        let Err(error) = use_case.execute(progress, cancel) else {
            panic!("a cancelled import must not complete");
        };
        let left: Vec<_> = match std::fs::read_dir(&out) {
            Ok(entries) => entries.flatten().map(|e| e.file_name()).collect(),
            Err(e) => panic!("the output folder: {e}"),
        };
        (
            left,
            ProjectImportFailure::from_any_message(&error.to_string()).reason,
        )
    }

    /// A cancelled import ends as the typed cancellation and leaves nothing on disk: no
    /// project, no staged file, no research folder. Cancelled before it starts, while the
    /// project is read (every read after it is refused), and between two rows.
    #[test]
    fn a_cancelled_import_leaves_nothing_behind() {
        use std::sync::atomic::{AtomicUsize, Ordering};
        // The second row converted: the titles of the rows follow the converting phase.
        let converting = AtomicBool::new(false);
        let rows = AtomicUsize::new(0);
        let between_rows = move |message: &str| {
            if message == "import.converting" {
                converting.store(true, Ordering::Relaxed);
                return false;
            }
            converting.load(Ordering::Relaxed)
                && !message.starts_with("import.")
                && rows.fetch_add(1, Ordering::Relaxed) + 1 >= 2
        };
        let stops: [(&str, bool, StopAt); 3] = [
            ("before it starts", true, Box::new(|_| false)),
            (
                "while reading",
                false,
                Box::new(|message| message == "import.opening"),
            ),
            ("between rows", false, Box::new(between_rows)),
        ];
        for (when, preset, stop_at) in stops {
            let (left, reason) = cancelled_at(preset, stop_at);
            assert_eq!(reason, FailureReason::Cancelled, "cancelled {when}");
            assert!(left.is_empty(), "cancelled {when}, left behind: {left:?}");
        }
    }
}
